"use client";

import { useEffect, useRef } from "react";

interface Star {
  x: number;
  y: number;
  r: number;
  baseAlpha: number;
  phase: number;
  speed: number;
  hue: "gold" | "white" | "warm";
}

interface Comet {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
}

/**
 * A gentle canvas starfield — twinkling stars with the occasional
 * golden shooting star. Rendered above the hero painting.
 */
export function Starfield({ density = 0.00012 }: { density?: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;
    let stars: Star[] = [];
    let comets: Comet[] = [];
    let nextCometAt = performance.now() + 3500;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    const resize = () => {
      const { clientWidth: w, clientHeight: h } = canvas;
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const count = Math.floor(w * h * density);
      stars = Array.from({ length: count }, () => {
        const roll = Math.random();
        return {
          x: Math.random() * w,
          y: Math.random() * h,
          r: 0.6 + Math.random() * 1.7,
          baseAlpha: 0.35 + Math.random() * 0.5,
          phase: Math.random() * Math.PI * 2,
          speed: 0.4 + Math.random() * 1.1,
          hue: roll < 0.45 ? "gold" : roll < 0.8 ? "white" : "warm",
        };
      });
    };

    const starColor = (s: Star, alpha: number) => {
      switch (s.hue) {
        case "gold":
          return `rgba(240, 205, 120, ${alpha})`;
        case "warm":
          return `rgba(255, 230, 200, ${alpha})`;
        default:
          return `rgba(245, 248, 255, ${alpha})`;
      }
    };

    const draw = (t: number) => {
      const { clientWidth: w, clientHeight: h } = canvas;
      ctx.clearRect(0, 0, w, h);

      // stars
      for (const s of stars) {
        const tw = s.baseAlpha * (0.55 + 0.45 * Math.sin(s.phase + t * 0.001 * s.speed));
        const glow = s.r * 4;
        const g = ctx.createRadialGradient(s.x, s.y, 0, s.x, s.y, glow);
        g.addColorStop(0, starColor(s, tw * 0.9));
        g.addColorStop(1, starColor(s, 0));
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(s.x, s.y, glow, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = starColor(s, tw);
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fill();
      }

      // spawn comets
      if (t > nextCometAt) {
        nextCometAt = t + 5000 + Math.random() * 6000;
        const fromLeft = Math.random() > 0.5;
        comets.push({
          x: fromLeft ? -40 : w * (0.3 + Math.random() * 0.7),
          y: h * (0.05 + Math.random() * 0.35),
          vx: (fromLeft ? 1 : -1) * (3.2 + Math.random() * 2),
          vy: 1.4 + Math.random() * 1.2,
          life: 0,
          maxLife: 90 + Math.random() * 40,
        });
      }

      // comets
      comets = comets.filter((c) => c.life < c.maxLife);
      for (const c of comets) {
        c.life += 1;
        c.x += c.vx;
        c.y += c.vy;
        const fade = Math.sin((c.life / c.maxLife) * Math.PI);
        const tail = 90;
        const g = ctx.createLinearGradient(c.x, c.y, c.x - c.vx * tail * 0.16, c.y - c.vy * tail * 0.16);
        g.addColorStop(0, `rgba(244, 214, 140, ${0.85 * fade})`);
        g.addColorStop(1, "rgba(244, 214, 140, 0)");
        ctx.strokeStyle = g;
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(c.x, c.y);
        ctx.lineTo(c.x - c.vx * tail * 0.16, c.y - c.vy * tail * 0.16);
        ctx.stroke();

        ctx.fillStyle = `rgba(250, 235, 190, ${0.9 * fade})`;
        ctx.beginPath();
        ctx.arc(c.x, c.y, 1.8, 0, Math.PI * 2);
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };

    resize();
    raf = requestAnimationFrame(draw);
    window.addEventListener("resize", resize);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
    };
  }, [density]);

  return (
    <canvas
      ref={canvasRef}
      className="pointer-events-none absolute inset-0 h-full w-full"
      aria-hidden
    />
  );
}
